package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.*;import org.springframework.stereotype.Component;import java.util.*;
@Component public class HeadingAwareChunkingStrategy implements ChunkingStrategy {public String code(){return "HEADING_AWARE";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){List<ChunkFragment>out=new ArrayList<>();for(ParsedSection s:d.getSections()){String heading=ChunkingSupport.headings(s.getHeadingPath());String text=p.isPreserveHeading()&&heading!=null?heading+"\n"+s.getText():s.getText();out.addAll(ChunkingSupport.windows(text,p,s.getPage(),s.getTitle(),heading,s.getSourceOffsetStart()));}return out;}}
